text(await tools.exec_command({cmd:"cat > src/bulk.mbt <<'MBT'
///|
pub let usage : String =
  "Usage: orca-env-devsy <status|stop [--force]|resume> --provider <name> [--jobs <n>]\n       orca-env-devsy recipe <create|resume|suspend|destroy|recover|restart>\n       orca-env-devsy <recover|restart>\n"

///|
struct BulkOptions {
  provider : String
  jobs : Int
  force : Bool
}

///|
fn bulk_options(mode : String, args : Array[String]) -> BulkOptions raise {
  let mut provider = None
  let mut jobs = 4
  let mut force = false
  let mut i = 0
  while i < args.length() {
    match args[i] {
      "--provider" if i + 1 < args.length() && provider is None => {
        i += 1
        provider = Some(args[i])
      }
      "--jobs" if i + 1 < args.length() => {
        i += 1
        jobs = @string.parse_int(args[i])
      }
      "--force" if mode == "stop" && !force => force = true
      _ => raise AdapterError("Invalid bulk option: " + args[i])
    }
    i += 1
  }
  guard provider is Some(provider) && valid_context(provider) && jobs > 0 && jobs <= 64 else {
    raise AdapterError("--provider is required; --jobs must be between 1 and 64")
  }
  { provider, jobs, force }
}

///|
async fn observe_activity(state : Json) -> Json {
  let directory = required(state, "tunnelDirectory")
  let pairing = if @fs.exists(directory + "/pairing-code") {
    @fs.read_file(directory + "/pairing-code").text()
  } else {
    ""
  }
  let script = (if field(state, "orcaVolume") is Some(_) {
      "ORCA_USER_DATA_PATH=/workspaces/.orca/.profile "
    } else {
      ""
    }) +
    "ELECTRON_RUN_AS_NODE=1 \"$HOME/.local/share/orca-env-devsy/orca/current/orca-ide\" -e " +
    quote(activity_probe_source())
  let (input, writer) = @process.write_to_process()
  defer writer.close()
  let (output, reader) = @process.read_from_process()
  defer output.close()
  let sink = @process.redirect_to_file("/dev/null", shared=true)
  defer sink.close()
  @async.with_timeout(30000, async fn() {
    @async.with_task_group(async fn(group) {
      let child = @process.spawn(
        group, "ssh", ssh_args(state, services=false) + [script],
        stdin=input, stdout=reader, stderr=sink,
      )
      let reading = group.spawn(async fn() {
        let buffer = @buffer.Buffer()
        let bytes = FixedArray::make(4096, b'\x00')
        while true {
          let count = output.read(bytes)
          if count == 0 { break }
          guard buffer.length() + count <= 4194304 else {
            raise AdapterError("Activity response too large")
          }
          buffer.write_bytes(bytes[:count].to_bytes())
        }
        @utf8.decode(buffer.to_bytes())
      })
      let payload : Json = { "pairingCode": pairing }
      writer.write(payload.stringify())
      writer.close()
      guard child.wait() == 0 else { raise AdapterError("Remote activity probe failed") }
      let value = @json.parse(reading.wait())
      guard field(value, "schemaVersion") == Some(Json::number(1)) &&
        ["idle", "active", "unknown"].contains(required(value, "activity")) else {
        raise AdapterError("Invalid activity response")
      }
      value
    })
  })
}

///|
fn unknown_activity(reason : String) -> Json {
  { "activity": "unknown", "reason": redact_credentials(reason) }
}

///|
async fn bulk_context(state : Json) -> String {
  let selection = @json.parse(state.stringify())
  if selection is Json::Object(fields) { fields.remove("context") }
  let contexts = @json.parse(devsy(selection, ["--result-format", "json", "context", "list"], "bulk-context"))
  guard contexts is Json::Array(items) else { raise AdapterError("Invalid context list") }
  let selected = items.filter(item => field(item, "default") == Some(Json::boolean(true)))
  guard selected.length() == 1 else { raise AdapterError("No unique effective Devsy context") }
  required(selected[0], "name")
}

///|
async fn bulk_identity(state : Json, provider : String) -> (Bool, Bool) {
  let current = workspace(state)
  match current {
    None => (true, false)
    Some(value) => {
      let actual_provider = field(value, "provider").map(p => field(p, "name")).flatten()
      let in_scope = actual_provider == Some(Json::string(provider)) &&
        field(value, "context").map(c => c == field(state, "context").unwrap()).unwrap_or(true)
      (in_scope, in_scope && field(value, "uid") == field(state, "workspaceUid"))
    }
  }
}

///|
async fn bulk_one(mode : String, state : Json, options : BulkOptions) -> Json? {
  let id = required(state, "workspaceId")
  let result : Json = {
    "id": id, "uid": required(state, "workspaceUid"),
    "context": required(state, "context"), "provider": options.provider,
    "vmStatus": "unknown", "activity": "unknown", "outcome": "skipped",
  }
  try {
    guard required(state, "context") == bulk_context(state) else { return None }
    let lock = connection_operation_lock(state)
    defer lock.close()
    let (in_scope, matched) = bulk_identity(state, options.provider)
    guard in_scope else { return None }
    set_field(result, "identityVerified", Json::boolean(matched))
    guard matched else {
      set_field(result, "evidence", unknown_activity("workspace_missing_or_replaced"))
      return Some(result)
    }
    let status = workspace_status(state)
    set_field(result, "vmStatus", Json::string(status))
    let evidence = if status != "Running" {
      unknown_activity("workspace_not_running")
    } else if options.force {
      unknown_activity("forced_without_activity_check")
    } else {
      try {
        observe_activity(state)
      } catch {
        error => unknown_activity(error.to_string())
      }
    }
    set_field(result, "activity", field(evidence, "activity").unwrap())
    set_field(result, "evidence", evidence)
    save_diagnostic("bulk-observation", mode, tunnel_directory=required(state, "tunnelDirectory"), evidence=result)
    if mode == "status" {
      set_field(result, "outcome", Json::string("observed"))
      return Some(result)
    }
    if mode == "stop" {
      if status == "Stopped" {
        set_field(result, "reason", Json::string("already_stopped"))
      } else if !options.force && (status != "Running" || field(evidence, "activity") != Some(Json::string("idle"))) {
        set_field(result, "reason", Json::string("not_idle"))
      } else {
        let (scope, valid) = bulk_identity(state, options.provider)
        guard scope && valid else { raise AdapterError("Workspace changed before stop") }
        pause_tunnel(state)
        defer unpause_tunnel(state)
        ignore(devsy(state, ["workspace", "stop", id], "workspace-stop"))
        set_field(result, "outcome", Json::string("success"))
      }
    } else {
      if status == "Running" {
        set_field(result, "reason", Json::string("already_running"))
      } else if status != "Stopped" {
        set_field(result, "reason", Json::string("workspace_not_stopped"))
      } else {
        let (scope, valid) = bulk_identity(state, options.provider)
        guard scope && valid else { raise AdapterError("Workspace changed before resume") }
        unpause_tunnel(state)
        ignore(devsy(state, ["--result-format", "json", "workspace", "up", "--id", id, "--ide-launch", "skip"] + orca_storage_args(state), "workspace-resume"))
        recover_connection(state)
        set_field(result, "outcome", Json::string("success"))
      }
    }
  } catch {
    error => {
      set_field(result, "outcome", Json::string("failed"))
      set_field(result, "error", Json::string(redact_credentials(error.to_string())))
    }
  }
  save_diagnostic("bulk-workspace", mode, evidence=result)
  Some(result)
}

///|
pub async fn bulk(mode : String, args : Array[String]) -> Unit {
  let options = bulk_options(mode, args)
  save_diagnostic("bulk", "started", evidence={ "action": mode, "provider": options.provider, "jobs": options.jobs, "force": options.force })
  let base = adapter_state_home() + "/tunnels"
  let states : Array[Json] = []
  if @fs.exists(base) {
    for name in @fs.readdir(base, sort=true) {
      let directory = base + "/" + name
      if @fs.kind(directory, follow_symlink=false) != @fs.FileKind::Directory || !@fs.exists(directory + "/enabled") { continue }
      let state = @json.parse(@fs.read_file(directory + "/state.json").text())
      validate_state(state)
      ignore(required(state, "workspaceUid"))
      set_field(state, "tunnelDirectory", Json::string(directory))
      states.push(state)
    }
  }
  let keys : Map[String, Bool] = {}
  for state in states {
    let key = required(state, "context") + ":" + required(state, "workspaceUid")
    guard !keys.contains(key) else { raise AdapterError("Duplicate saved workspace identity") }
    keys.set(key, true)
  }
  let results : Array[Json] = []
  let permits = @async.Semaphore(options.jobs)
  @async.with_task_group(async fn(group) {
    for state in states {
      permits.acquire()
      group.spawn_bg(async fn() {
        defer permits.release()
        if bulk_one(mode, state, options) is Some(result) { results.push(result) }
      })
    }
  })
  results.sort_by((a, b) => required(a, "id").compare(required(b, "id")))
  let failures = results.filter(r => field(r, "outcome") == Some(Json::string("failed"))).length()
  let output : Json = { "schemaVersion": 1, "action": mode, "provider": options.provider, "workspaces": results, "failed": failures }
  @stdio.stdout.write(output.stringify(indent=2) + "\n")
  save_diagnostic("bulk", if failures == 0 { "success" } else { "failed" }, evidence=output)
  guard failures == 0 else { raise AdapterError("Some workspace operations failed") }
}
