///|
extern "C" fn idle_clock_ms() -> Int64 = "orca_idle_clock_ms"

///|
fn parse_idle_timeout(value : String) -> Int64 raise ConfigError {
  let (digits, scale) = if value.has_suffix("s") {
    (value[:value.length() - 1].to_owned(), 1000L)
  } else if value.has_suffix("m") {
    (value[:value.length() - 1].to_owned(), 60000L)
  } else if value.has_suffix("h") {
    (value[:value.length() - 1].to_owned(), 3600000L)
  } else if value.has_suffix("d") {
    (value[:value.length() - 1].to_owned(), 86400000L)
  } else {
    raise InvalidConfig("idleTimeout must be a positive integer followed by s, m, h or d")
  }
  guard digits != "" && digits.to_array().iter().all(c => c >= '0' && c <= '9') else {
    raise InvalidConfig("Invalid idleTimeout duration")
  }
  let amount = @string.parse_int64(digits) catch { _ => raise InvalidConfig("idleTimeout is too large") }
  guard amount > 0 && amount <= 9007199254740991L / scale else {
    raise InvalidConfig("idleTimeout must be positive and exactly representable")
  }
  amount * scale
}

///|
fn idle_timeout(state : Json) -> Int64? raise {
  match field(state, "idleTimeoutMs") {
    None => None
    Some(Json::Number(n, ..)) if n > 0 && n <= 9007199254740991.0 && n == n.to_int64().to_double() => Some(n.to_int64())
    _ => raise AdapterError("Invalid saved idle timeout")
  }
}

///|
priv struct IdleTimer {
  mut elapsed : Int64
  mut seen : Bool
  mut previous : Int64?
  mut epoch : Int64
}

///|
fn IdleTimer::advance(self : IdleTimer, activity : String, now : Int64) -> Unit raise {
  guard now >= 0 else { raise AdapterError("Idle clock unavailable") }
  let delta = match self.previous { Some(last) if now >= last => now - last; _ => 0L }
  if activity == "active" {
    self.elapsed = 0
    self.seen = false
  } else if activity == "idle" || (activity == "unknown" && self.seen) {
    if self.seen { self.elapsed = min(9007199254740991L, self.elapsed + delta) }
    self.seen = true
  }
  self.previous = Some(now)
}

///|
async fn idle_state_lock(state : Json) -> @fs.File {
  let lock = @fs.open(required(state, "tunnelDirectory") + "/idle-state.lock", mode=ReadWrite, create_mode=OpenOrCreate, permission=0o600)
  errdefer lock.close()
  @async.with_timeout(2000, async fn() { while !lock.try_lock(Exclusive) { @async.sleep(10) } })
  lock
}

///|
async fn idle_record(state : Json) -> Json {
  let path = required(state, "tunnelDirectory") + "/idle.json"
  if !@fs.exists(path) {
    return { "uid": required(state, "workspaceUid"), "elapsedMs": 0, "seenIdle": false, "epoch": 0, "reason": "awaiting_idle", "activity": "unknown" }
  }
  let record = @json.parse(@fs.read_file(path).text())
  guard field(record, "uid") == field(state, "workspaceUid") &&
    field(record, "elapsedMs") is Some(Json::Number(elapsed, ..)) && elapsed >= 0 && elapsed <= 9007199254740991.0 && elapsed == elapsed.to_int64().to_double() &&
    field(record, "epoch") is Some(Json::Number(epoch, ..)) && epoch >= 0 && epoch <= 9007199254740991.0 && epoch == epoch.to_int64().to_double() &&
    (field(record, "seenIdle") == Some(Json::boolean(true)) || field(record, "seenIdle") == Some(Json::boolean(false))) else {
    raise AdapterError("Invalid saved idle timer")
  }
  record
}

///|
async fn idle_write(state : Json, record : Json) -> Unit {
  let path = required(state, "tunnelDirectory") + "/idle"
  @fs.write_file(path + ".tmp", record.stringify(), permission=0o600)
  @fs.rename(path + ".tmp", path + ".json", replace=true)
}

///|
async fn idle_reset(state : Json, reason : String) -> Unit {
  if idle_timeout(state) is None { return }
  let lock = idle_state_lock(state)
  defer lock.close()
  let old = idle_record(state)
  if field(old, "elapsedMs") == Some(Json::number(0)) && field(old, "seenIdle") == Some(Json::boolean(false)) && field(old, "reason") == Some(Json::string(reason)) { return }
  let epoch = match field(old, "epoch") { Some(Json::Number(n, ..)) => n.to_int64() + 1; _ => 1L }
  let record : Json = { "uid": required(state, "workspaceUid"), "elapsedMs": 0, "seenIdle": false, "epoch": Json::number(epoch.to_double()), "activity": "unknown", "reason": reason, "observedAt": @env.now().to_string() }
  idle_write(state, record)
  save_diagnostic("idle-reset", reason, tunnel_directory=required(state, "tunnelDirectory"), evidence=record)
}

///|
async fn idle_tick(state : Json, timer : IdleTimer, activity : String, reason : String, now : Int64) -> Unit {
  let lock = idle_state_lock(state)
  defer lock.close()
  let old = idle_record(state)
  let epoch = match field(old, "epoch") { Some(Json::Number(n, ..)) => n.to_int64(); _ => 0L }
  if epoch != timer.epoch {
    timer.elapsed = match field(old, "elapsedMs") { Some(Json::Number(n, ..)) => n.to_int64(); _ => 0L }
    timer.seen = field(old, "seenIdle") == Some(Json::boolean(true))
    timer.previous = None
    timer.epoch = epoch
  }
  timer.advance(activity, now)
  let record : Json = { "uid": required(state, "workspaceUid"), "epoch": Json::number(epoch.to_double()), "elapsedMs": Json::number(timer.elapsed.to_double()), "seenIdle": timer.seen, "activity": activity, "reason": reason, "observedAt": @env.now().to_string() }
  idle_write(state, record)
  save_diagnostic("idle-observation", reason, tunnel_directory=required(state, "tunnelDirectory"), evidence={ "timeoutMs": field(state, "idleTimeoutMs").unwrap(), "before": old, "after": record })
}

///|
async fn idle_status(state : Json) -> Json {
  guard idle_timeout(state) is Some(timeout) else { return { "enabled": false } }
  let result : Json = { "enabled": true, "timeoutMs": Json::number(timeout.to_double()), "elapsedMs": 0, "reason": "initializing" }
  try {
    let record = idle_record(state)
    for name in ["elapsedMs", "reason", "activity", "observedAt"] {
      if field(record, name) is Some(value) { set_field(result, name, value) }
    }
  } catch { error => { set_field(result, "reason", Json::string("timer_unavailable")); set_field(result, "error", Json::string(redact_credentials(error.to_string()))) } }
  result
}

///|
async fn stop_workspace(state : Json) -> Unit {
  ignore(devsy(state, ["workspace", "stop", required(state, "workspaceId")], "workspace-stop"))
  idle_reset(state, "workspace_stopped")
}

///|
priv struct IdleSession {
  child : @process.Process
  writer : @process.WriteToProcess
  reader : @process.ReadFromProcess
}

///|
async fn IdleSession::read(self : IdleSession) -> Json {
  let buffer = @buffer.Buffer()
  let bytes = FixedArray::make(4096, b'\x00')
  while true {
    let count = self.reader.read(bytes)
    guard count > 0 else { raise AdapterError("Idle observer disconnected") }
    guard buffer.length() + count <= 4194304 else { raise AdapterError("Idle observer response too large") }
    buffer.write_bytes(Bytes::from_array(bytes[:count].to_owned()))
    if bytes[count - 1] == b'\n' { break }
  }
  @json.parse(@utf8.decode(buffer.to_bytes()))
}

///|
async fn IdleSession::observe(self : IdleSession) -> Json {
  @async.with_timeout(30000, async fn() {
    self.writer.write("observe\n")
    let value = self.read()
    guard field(value, "schemaVersion") == Some(Json::number(1)) && ["idle", "active", "unknown"].contains(required(value, "activity")) else { raise AdapterError("Invalid idle observer result") }
    value
  })
}

///|
async fn IdleSession::close(self : IdleSession) -> Unit {
  self.writer.close()
  self.reader.close()
  self.child.cancel()
  @async.with_timeout(2000, async fn() { ignore(self.child.wait()) }) catch { _ => () }
}

///|
async fn[X] open_idle_session(group : @async.TaskGroup[X], state : Json) -> IdleSession {
  let directory = required(state, "tunnelDirectory")
  guard @fs.exists(directory + "/pairing-code") else { raise AdapterError("Native access unavailable for idle observer") }
  let pairing = @fs.read_file(directory + "/pairing-code").text()
  let (input, writer) = @process.write_to_process()
  let (reader, output) = @process.read_from_process()
  let sink = @process.redirect_to_file("/dev/null", shared=true)
  defer sink.close()
  let script = "ORCA_ENV_DEVSY_OBSERVER=1 " + activity_command(state)
  let child = @process.spawn(group, "ssh", ["-o", "ProxyCommand=false", "-o", "ControlMaster=no"] + ssh_args(state, services=false) + ["-S", control_socket(state, directory), script], stdin=input, stdout=output, stderr=sink, no_wait=true)
  let session = { child, writer, reader }
  errdefer @async.protect_from_cancel(async fn() { session.close() })
  @async.with_timeout(30000, async fn() {
    writer.write(({ "pairingCode": pairing } : Json).stringify() + "\n")
    let ready = session.read()
    guard field(ready, "ready") == Some(Json::boolean(true)) else { raise AdapterError("Idle observer initialization failed") }
  })
  save_diagnostic("idle-connection", "connected", tunnel_directory=directory)
  session
}

///|
async fn idle_supervisor(state : Json, busy : Ref[Bool], done : Ref[Bool]) -> Unit {
  let timeout = idle_timeout(state).unwrap()
  let record = idle_record(state)
  let timer : IdleTimer = { elapsed: match field(record, "elapsedMs") { Some(Json::Number(n, ..)) => n.to_int64(); _ => 0L }, seen: field(record, "seenIdle") == Some(Json::boolean(true)), epoch: -1, previous: None }
  let interval = configured_timing_ms("ORCA_ENV_DEVSY_TEST_IDLE_POLL_MS", 30000)
  let mut attempt = 0
  while @fs.exists(required(state, "tunnelDirectory") + "/enabled") {
    let outcome = try {
      @async.with_task_group(async fn(group) {
        let session = open_idle_session(group, state)
        defer @async.protect_from_cancel(async fn() { session.close() })
        attempt = 0
        while true {
          let started = idle_clock_ms()
          let evidence = session.observe()
          let activity = required(evidence, "activity")
          idle_tick(state, timer, activity, if activity == "unknown" { "observation_unknown" } else { "monitoring" }, idle_clock_ms())
          if timer.elapsed >= timeout && activity == "idle" {
            let lock = connection_operation_lock(state)
            defer lock.close()
            guard !@fs.exists(required(state, "tunnelDirectory") + "/paused") else { return false }
            let (scope, identity) = bulk_identity(state, required(state, "idleProvider"))
            guard scope && identity && workspace_status(state) == "Running" else { raise AdapterError("Idle stop identity or running state changed") }
            let fresh = session.observe()
            let current = required(fresh, "activity")
            idle_tick(state, timer, current, if current == "unknown" { "awaiting_idle_confirmation" } else { "monitoring" }, idle_clock_ms())
            if current == "idle" {
              busy.val = true
              defer busy.val = false
              save_diagnostic("idle-stop", "started", tunnel_directory=required(state, "tunnelDirectory"), evidence=fresh)
              session.close()
              try { stop_workspace(state) } catch { error => { save_diagnostic("idle-stop", "failed", error_type="workspace_stop_failed", error_message=redact_credentials(error.to_string()), tunnel_directory=required(state, "tunnelDirectory")); raise error } }
              save_diagnostic("idle-stop", "success", tunnel_directory=required(state, "tunnelDirectory"))
              done.val = true
              return true
            }
          }
          let elapsed = idle_clock_ms() - started
          @async.sleep(if elapsed >= interval.to_int64() { 0 } else { interval - elapsed.to_int() })
        }
      })
    } catch { error => {
      save_diagnostic("idle-connection", "failed", error_type="observer_unavailable", error_message=redact_credentials(error.to_string()), tunnel_directory=required(state, "tunnelDirectory"))
      false
    } }
    if outcome { return }
    let cycles = 1 << min(attempt, 4)
    attempt = min(attempt + 1, 4)
    save_diagnostic("idle-connection", "retry", attempt~, retry_delay_ms=interval * cycles, tunnel_directory=required(state, "tunnelDirectory"))
    for _ in 0..<cycles {
      idle_tick(state, timer, "unknown", "observer_reconnecting", idle_clock_ms())
      @async.sleep(interval)
    }
  }
}
